MATCH (e:PlantItem {tag: 'E-24701'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (loop:ProcessInstrumentationFunction {loop_tag: 'HS-584005'})-[:send_signal_to*]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (e:PlantItem {tag: 'P-10501'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (v:GateValve:PlantItem {unit_id: '322'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(e:PlantItem {tag: 'E-6701'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'E-10601'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (tank:PlantItem {tag: 'TK-1304'})-[:line_to]-(valve:Valve)<-[:control]-(actuator:ActuatingFunction)<-[:send_signal_to*]-(loop:ProcessControlFunction)
RETURN DISTINCT loop.loop_tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'P-41702'})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (e:Equipment)-[:measured_by]->(s:PlantItem)
WHERE EXISTS {
  (s)-[:send_signal_to*0..]->(:ProcessInstrumentationFunction {loop_tag: 'PI-405024'})
}
RETURN DISTINCT e.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-21203'}), (b:PlantItem {tag: 'P-21303'})
RETURN a.tag AS tag1, a.unit_id AS unit1, b.tag AS tag2, b.unit_id AS unit2
}

MATCH (i:PlantItem {tag: 'V-9501'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (:PlantItem {tag: 'EJ-25501A'})-[:is_drawn_on]->(s:Sheet)
RETURN s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (:PlantItem {tag: 'EA-28201'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(e:PlantItem:Equipment {tag: 'E-12602'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'E-49102'})-[:is_drawn_on]->(s:Sheet)
RETURN s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (v:PlantItem:SpringLoadedGlobeSafetyValve {unit_id: '475'})
RETURN v.tag AS tag
ORDER BY tag;
